// One item per image URL, duplicates removed.
const found = $input.first().json.images || []
const urls = [...new Set(found.map(img => img.url || img.src || img).filter(u => typeof u === 'string' && u.startsWith('http')))]
if (!urls.length) {
  throw new Error('No images found on this page. Check the URL in Settings, or turn on Additional Options > Render in a Browser in the MiroMiro node for images that load on scroll.')
}
return urls.map(url => ({ json: { url }, pairedItem: { item: 0 } }))

// Every downloaded image on one item, so they land in one zip.
// Items without a file are failed downloads (skipped, not fatal).
const binary = {}
let failed = 0
$input.all().forEach((item, i) => {
  if (item.binary?.data) binary['image_' + String(i + 1).padStart(3, '0')] = item.binary.data
  else failed++
})
if (!Object.keys(binary).length) throw new Error('None of the images could be downloaded. The site may block direct downloads.')
return [{ json: { downloaded: Object.keys(binary).length, failed }, binary, pairedItem: { item: 0 } }]
